-- =====================================================================
-- Avatars: animated (pulse) SVG avatars users can pick in Profile.
-- Admin manages them (add single + batch upload, toggle, delete).
-- SVG markup stored inline (Render FS is ephemeral).
-- Adds users.avatar_id. Seeds one default avatar.
-- Idempotent via IF NOT EXISTS + ON CONFLICT (slug) DO NOTHING.
-- =====================================================================

CREATE TABLE IF NOT EXISTS avatars (
  id          BIGSERIAL PRIMARY KEY,
  slug        TEXT UNIQUE NOT NULL,
  name        TEXT NOT NULL,
  svg         TEXT NOT NULL,
  active      BOOLEAN DEFAULT true,
  sort_order  INT DEFAULT 100,
  created_at  TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE users
  ADD COLUMN IF NOT EXISTS avatar_id BIGINT REFERENCES avatars(id) ON DELETE SET NULL;

